require("LocalData/BingoeventLocalData")
require("LocalData/BingopoolLocalData")
require("LocalData/BingoopenLocalData")
local BingoActivityData = require("Model/Activity/ActivityData/BingoActivityData")

-- 硬编码
local Const = {
    [47000] = {
        xLen = 7,
        yLen = 7,
    }
}


---@class BingoViewModel
BingoViewModel = {}

---@private
---@type table<int, BingoActivityData> @ key - activityId
BingoViewModel._activityDataMap = {}
---@private
BingoViewModel._bGotData = false


--region 辅助方法

---@private
---@param activityId int
---@param points NDATA_BingoInfo[]
function BingoViewModel._BuildBingoData(activityId, points)
    local const = Const[activityId]
    if not const then
        Global.LogError("未找到Bingo活动(%s)硬编码配置")
        const = {}
    end
    
    ---@type BingoActivityData
    local actData = BingoActivityData.New(activityId, const)
    actData:PushPoints(points)
    BingoViewModel._activityDataMap[activityId] = actData
end

---@private
---@param activityId int
---@param bNoSure boolean @ 不再返回空对象
---@return BingoActivityData @ 活动不存在或未开启，也会返回空对象
function BingoViewModel._GetBingoData(activityId, bNoSure)
    local actData = BingoViewModel._activityDataMap[activityId]
    if actData then
        return actData
    end
    
    Global.LogError(string.format("Bingo活动(%s)不存在或未开启", activityId))
    if bNoSure then
        return nil
    end
    return BingoActivityData.New(activityId, CheckTable(Const[activityId]))
end

---@private
---@param points NDATA_BingoInfo[]
---@return goods[]
function BingoViewModel._IntegrateRewards(points)
    ---@type goods[]
    local goods = {}

    for _, p in pairs(points) do
        for _, pg in pairs(p.goods) do
            local bNew = true
            
            for _, g in ipairs(goods) do
                if g.goodsID == pg.goodsID and g.goodsType == pg.goodsType then
                    g.goodsNum = g.goodsNum + pg.goodsNum
                    bNew = false
                    break
                end
            end

            if bNew then
                -- 不克隆新表，则会在有重复物品时，道具数量被修改
                table.insert(goods, Copy(pg))
            end
        end
    end
    
    return goods
end

---@private
---@param points NDATA_BingoInfo[]
function BingoViewModel._PreprocessNDATAPoints(points)
    for _, p in pairs(points) do
        p.x = p.x + 1
        p.y = p.y + 1
    end
end

--endregion 辅助方法


--region 用户操作

--- 从后端更新数据
---@param activityId int
---@param onUpdateFinish fun()?
function BingoViewModel.UpdateData(activityId, onUpdateFinish)
    if not activityId or activityId == 0 then
        Global.LogError("传入了空的活动id")
        if onUpdateFinish then
            onUpdateFinish()
        end
        return
    end
    
    local reqData = {
        activityId = activityId,
    }
    BingoViewModel._BingoInfoREQ(reqData, function(tab)
        BingoViewModel._bGotData = true
        
        local points = CheckTable(tab.point)
        BingoViewModel._PreprocessNDATAPoints(points)
        BingoViewModel._BuildBingoData(activityId, points)
        if onUpdateFinish then
            onUpdateFinish()
        end
    end)
end

--- 领取任务奖励
---@param activityId int
---@param taskId int @ nil / 0 表示全部领取
---@param onClaimFinish fun()?
function BingoViewModel.ClaimTask(activityId, taskId, onClaimFinish)
    local actData = BingoViewModel._GetBingoData(activityId, true)
    if not actData then
        if onClaimFinish then
            onClaimFinish()
        end
        return
    end
    
    AchievementViewModel.TaskPerform(TaskControl.DayTaskType.EVENT_RAID, taskId or 0, nil, actData.taskGroupId, function() 
        Event.Go("ActivityDot")
        if onClaimFinish then
            onClaimFinish()
        end
    end)
end

--- 翻牌
---@param activityId int
---@param stage int
---@param x int
---@param y int
---@param onFlipFinish fun(points:NDATA_BingoInfo[], rewards:goods[])? @ points-新打开的格子
function BingoViewModel.FlipCard(activityId, stage, x, y, onFlipFinish)
    if not activityId or activityId == 0 then
        Global.LogError("传入了空的活动id")
        if onFlipFinish then
            onFlipFinish({}, {})
        end
        return
    end
    
    local reqData = {
        activityId = activityId,
        stage = stage,
        -- 需要调整为 0-based
        x = x - 1,
        y = y - 1,
    }
    BingoViewModel._BingoDrawREQ(reqData, function(tab)
        local points = CheckTable(tab.point)
        BingoViewModel._PreprocessNDATAPoints(points)
        
        local actData = BingoViewModel._GetBingoData(activityId, true)
        if actData then
            actData:PushPoints(points)
            
            -- 道具消耗
            local costGoods = actData:GetCostGoods(stage)
            ItemControl.PushSingleItemData(costGoods, ItemControl.PushEnum.consume)
        end

        -- 奖励获取
        local rewards = BingoViewModel._IntegrateRewards(points)
        ItemControl.PushGroupItemData(rewards, ItemControl.PushEnum.add)

        Event.Go("ActivityDot")

        if onFlipFinish then
            onFlipFinish(points, rewards)
        end
    end)
end

