---@private
---@param data table
---@param callback fun(tab:table)
function BingoViewModel._BingoInfoREQ(data, callback)
    local bytes = assert(pb.encode("PBClient.ClientBingoInfoReq", data))
    MgrNet.SendReq(MID.CLIENT_BINGO_INFO_REQ, bytes, 0, nil, function(buffer, tag) 
        BingoViewModel._CommonACK("PBClient.ClientBingoInfoAck", MID.CLIENT_BINGO_INFO_REQ, buffer, tag)
    end, function(buffer, tag) 
        local tab = BingoViewModel._CommonNTF("PBClient.ClientBingoInfoNtf", MID.CLIENT_BINGO_INFO_REQ, buffer, tag)
        callback(tab)
    end)
end

---@private
---@param data table
---@param callback fun(tab:table)
function BingoViewModel._BingoDrawREQ(data, callback)
    local bytes = assert(pb.encode("PBClient.ClientBingoDrawReq", data))
    MgrNet.SendReq(MID.CLIENT_BINGO_DRAW_REQ, bytes, 0, nil, function(buffer, tag)
        BingoViewModel._CommonACK("PBClient.ClientBingoDrawAck", MID.CLIENT_BINGO_DRAW_REQ, buffer, tag)
    end, function(buffer, tag)
        local tab = BingoViewModel._CommonNTF("PBClient.ClientBingoDrawNtf", MID.CLIENT_BINGO_DRAW_REQ, buffer, tag)
        callback(tab)
    end)
end

---@private
---@return int
function BingoViewModel._CommonACK(pbKey, reqMid, buffer, tag)
    local tab = assert(pb.decode(pbKey, buffer))
    print(string.format("[ID:%s]errNo:%s", reqMid + 1, tab.errNo))
    if tab.errNo ~= 0 then
        Global.PopTip("Error" .. tab.errNo, 2, true)
    end
    return tab.errNo
end

---@private
---@return table
function BingoViewModel._CommonNTF(pbKey, reqMid, buffer, tag)
    local tab = assert(pb.decode(pbKey, buffer))
    print(string.format("[ID:%s]%s", reqMid + 2, tab))
    print(tab)
    return tab
end

