--region 活动数据

--- 初始化活动数据
--- 主要是为了获取红点数据
--- 只有登录时需要初始化获取，后续活动更新不需要，因为新开启 Bingo 不会自动翻开
function BingoViewModel.InitData()
    --- 遍历所有 Bingo 活动
    for _, config in pairs(BingoeventLocalData.tab) do
        local activityId = CheckNumber(config[2])
        -- 开启的 Bingo 活动，访问后端并初始化数据
        if BingoViewModel.CheckActivityOpen(activityId) then
            BingoViewModel.UpdateData(activityId, function() 
                -- 可能会很晚到达，因此需要触发更新
                Global.LogError(string.format("Bingo活动(%s)数据返回", activityId))
                -- 并非所有红点事件都会自行刷新红点
                BingoViewModel.RefreshAllRedDots()
                Event.Go(EID.BingoDataArrived)
                Event.Go("RedDotFunc")
                Event.Go("ActivityDot")
            end)
        end
    end
end

---@param activityId int
---@return boolean
function BingoViewModel.CheckActivityOpen(activityId)
    local activityData = ActivityControl.GetActivityByID(activityId)
    if not activityData then
        return false
    end

    return (activityData.systemopen == 0 or SysLockControl.CheckSysLock(activityData.systemopen)) and
            (activityData.timeType == 999 or Global.isMiddleTime(activityData.beginTime, activityData.endTime))
end

function BingoViewModel.RefreshAllRedDots()
    local bRedDot = false
    
    --- 有活动数据，只能代表登录游戏时活动是开启的
    for _, actData in pairs(BingoViewModel._activityDataMap) do
        --- 检查活动开启
        if BingoViewModel.CheckActivityOpen(actData.activityId) then
            --- 需要要有未翻开的格子，才检查红点
            if actData:HaveCoveredCell() then
                --- 日常任务
                local dayTaskList = TaskControl.GetEventRaidTaskData(actData.taskGroupId)
                ---@param task DayTaskData
                for _, task in pairs(dayTaskList) do
                    if task.isReceive == 1 then
                        bRedDot = true
                        break
                    end
                end
        
                --- 可翻开
                if not bRedDot then
                    bRedDot = actData:HaveFlippableCell()
                end
        
                --- 目前只有一个 Bingo 活动红点，所以直接跳出
                if bRedDot then
                    break
                end
            end
        end
    end
    
    --- 设置红点（如果要同时开多个 Bingo 活动，则要改到 for 内进行设置）
    local dotData = RedDotControl.GetDotData("Bingo")
    if dotData then
        dotData:SetState(bRedDot)
    else
        Global.LogError("红点数据'Bingo'不存在")
    end
end

---@param activityId int
---@return string @ yyyy/mm/dd/hh:MM-yyyy/mm/dd/hh:MM
function BingoViewModel.GetTimeStr(activityId)
    local activityData = ActivityControl.GetActivityByID(activityId)
    if not activityData then
        Global.LogError(string.format("活动(%s)数据不存在", activityId))
        return ""
    end
    -- 常驻
    if activityData.timeType == 999 then
        return ""
    end
    local bs = string.split(activityData.beginTime, "-")
    local es = string.split(activityData.endTime, "-")
    return string.format("%s/%s/%s/%s:%s-%s/%s/%s/%s:%s",
            bs[1], bs[2], bs[3], bs[4], bs[4],
            es[1], es[2], es[3], es[4], es[5])
end

